#pragma once
#include <juce_gui_basics/juce_gui_basics.h>
#include "FreeLfoFontData.h"   // generated by juce_add_binary_data (Inter, SIL Open Font License)

// The bundled UI font (Inter), so the plugin looks the same on every machine instead of using the system default.
namespace fonts
{
    inline juce::Typeface::Ptr regularFace()
    {
        static juce::Typeface::Ptr f = juce::Typeface::createSystemTypefaceFor(FreeLfoFontData::InterRegular_ttf, FreeLfoFontData::InterRegular_ttfSize);
        return f;
    }
    inline juce::Typeface::Ptr semiboldFace()
    {
        static juce::Typeface::Ptr f = juce::Typeface::createSystemTypefaceFor(FreeLfoFontData::InterSemiBold_ttf, FreeLfoFontData::InterSemiBold_ttfSize);
        return f;
    }
    inline juce::Font regular(float size)  { return juce::Font(juce::FontOptions(regularFace()).withHeight(size)); }
    inline juce::Font semibold(float size) { return juce::Font(juce::FontOptions(semiboldFace()).withHeight(size)); }
}
